function brandLogo(name){const [file,key]=clientLogos[name],b=logoBounds[key];const [w,h,x,y,bw,bh]=b,scale=Math.min(60/bh,150/bw,Math.sqrt(4000/(bw*bh)));return `<span class="client-logo client-${key}" title="${safe(name)}" style="width:${(bw*scale).toFixed(2)}px;height:${(bh*scale).toFixed(2)}px"><img src="${extraLogoAssets[file]||file}" alt="${safe(name||B('Collaborator logo','نشان همکار'))}" loading="eager" style="${['pouyan','tehran','namava'].includes(key)?'filter:url(#logo-white-mark);':key==='afamed'?'filter:url(#logo-green-mark);':key==='giti'?'filter:url(#logo-paper-mark);':key==='forklift'?'filter:url(#logo-forklift-mark);':['delpazir','mazmaz'].includes(key)?'filter:url(#logo-letter-mark);':key==='mark05'?'filter:url(#logo-alpha-clean) brightness(0) invert(1);':''}width:${(w*scale).toFixed(2)}px;height:${(h*scale).toFixed(2)}px;left:${(-x*scale).toFixed(2)}px;top:${(-y*scale).toFixed(2)}px"></span>`}
