function header(){return `<header class="topbar"><a class="brand" href="index.html" aria-label="${B('Home','خانه')}">SG</a><nav aria-label="${B('Main navigation','منوی اصلی')}" id="navigation">${[['home',B('HOME','خانه')],['works',B('SELECTED WORK','کارهای منتخب')],['backstage',B('BACKSTAGE','پشت‌صحنه')],['about',B('ABOUT ME','درباره من')]].map(([view,text])=>`<a ${route===view?'aria-current="page"':''} href="${view==='home'?'index.html':'?view='+view}">${text}</a>`).join('')}</nav><div class="header-controls"><button class="theme-toggle" type="button" aria-label="${B(theme==='dark'?'Switch to light theme':'Switch to dark theme',theme==='dark'?'تم روشن':'تم تیره')}" aria-pressed="${theme==='dark'}"><span aria-hidden="true">${theme==='dark'?'☀':'☾'}</span></button><div class="language" role="group" aria-label="${B('Language','زبان')}"><button data-lang="en" aria-pressed="${lang==='en'}">EN</button><button data-lang="fa" aria-pressed="${lang==='fa'}">فا</button></div><button class="menu-toggle" aria-controls="navigation" aria-expanded="false" aria-label="${B('Open menu','باز کردن منو')}"><span></span><span></span></button></div></header>`}
function hero(){return `<section class="hero" aria-label="${B('Introduction','معرفی')}"><div class="hero-images">${media.map((m,i)=>`<img src="${m}" alt="${B('Sadegh Golzadeh','صادق گل‌زاده')}" class="hero-image ${i===0?'active':''}" ${i===0?'fetchpriority="high"':'loading="eager"'}>`).join('')}</div><div class="hero-shade"></div><h1 class="first-name entrance">${B('SADEGH','صادق')}</h1><div class="vertical-meta"><span>2026</span></div><div class="hero-bottom"><p class="hero-tagline entrance">${B('CINEMATOGRAPHER · EDITOR<br>ART DIRECTOR','فیلم‌بردار و تدوین‌گر<br>مدیر هنری')}</p><div class="last-name entrance">${B('GOLZADEH','گل‌زاده')}</div></div><div class="hero-caption"><div class="slideshow-controls">${media.map((_,i)=>`<button class="slide-select ${i===0?'active':''}" data-slide="${i}" aria-label="${B('Show image','نمایش تصویر')} ${i+1}" aria-pressed="${i===0}">0${i+1}</button>`).join('')}<button class="slide-pause" aria-label="${B('Pause slideshow','توقف اسلایدها')}" aria-pressed="false">Ⅱ</button></div></div></section>`}
