function connect(){return `<div class="connect-block"><small>${B('CONNECT','در ارتباط باشیم')}</small><div class="connect-icons">${[['instagram','https://www.instagram.com/sadeghgolzadeh/','Instagram'],['whatsapp','https://wa.me/989143029104','WhatsApp'],['telegram','https://t.me/+989143029104','Telegram'],['linkedin','https://www.linkedin.com/in/sadeghgolzadeh/','LinkedIn'],['x','https://x.com/sadeghgolzadeh','X'],['spotify',spotify,'Spotify'],['mail','mailto:'+mail,B('Email','ایمیل')],['phone','tel:+989143029104',B('Phone','تلفن')]].filter(([i])=>!['x','spotify'].includes(i)||['about','thoughts'].includes(route)).map(([i,u,t])=>`<a class="connect-icon" href="${u}" aria-label="${t}" title="${t}" ${u.startsWith('https')?'target="_blank" rel="noopener noreferrer"':''}>${icon(i)}<span class="sr-only">${t}</span></a>`).join('')}</div></div>`}
function about(){return `<section id="about" class="about dark"><div class="wide"><div class="about-layout"><div class="about-copy reveal"><small class="section-kicker">${B('ABOUT ME','درباره من')}</small><h2 class="about-heading">${B('Behind the frames.','پشت این قاب‌ها.')}</h2><p class="reading-text" data-reading>${B('I shoot, edit, and manage productions — from independent projects to team productions for brands.','فیلم‌برداری، تدوین و مدیریت تولید؛ از پروژه‌های مستقل تا کارهای تیمی برای برندها.').split(' ').map(w=>`<span>${w}</span>`).join(' ')}</p><div class="bio"><p>${B('I work independently, from the first idea to the final edit. Before that, I led the studio team at <em>Faramouj</em>.','مستقل کار می‌کنم؛ از ایده‌ی اولیه تا تدوین نهایی. پیش از این، مدیریت تیم استودیوی <em>فراموج</em> رو به عهده داشتم.')}</p><p class="location-note">${B('Based in Tehran','ساکن تهران')} · <time class="clock" dir="ltr"></time></p></div><a class="text-link" href="?view=about">${B('A LITTLE MORE ABOUT ME ↗','کمی بیشتر درباره من ↗')}</a></div><figure class="about-portrait reveal"><img src="smoke.jpg" alt="${label()}" loading="lazy"><figcaption><span>${B('FILMMAKER / ART DIRECTOR','فیلم‌ساز / آرت دایرکتور')}</span></figcaption></figure></div></div></section>`}
